import com.super_awesome_baby.ares_hud.client.gui.screen.config.AresUIComponent;
import com.super_awesome_baby.ares_hud.client.gui.screen.config.AresUISetupScreen;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.resources.ResourceLocation;

public class DynamicStatusBarUIComponent
extends AresUIComponent {
    private final DynamicStatusBar bar;

    public DynamicStatusBarUIComponent(int x, int y, float initialScale, DynamicStatusBar bar, AresUISetupScreen parentScreen, AresUIComponent.SaveAction propertiesSaver) {
        super(x, y, 100, 12, initialScale, parentScreen, propertiesSaver);
        this.bar = bar;
    }

    public DynamicStatusBar getBar() {
        return this.bar;
    }

    @Override
    protected void renderContent(GuiGraphics guiGraphics, int mouseX, int mouseY, float partialTicks) {
        ResourceLocation background = switch (this.bar) {
            default -> throw new IncompatibleClassChangeError();
            case DynamicStatusBar.VEHICLE_HEALTH -> AresHudTextures.VEHICLE_HEALTH_BG;
            case DynamicStatusBar.AIR -> AresHudTextures.AIR_BAR_BG;
            case DynamicStatusBar.JUMP -> AresHudTextures.JUMP_BAR_BG;
        };
        ResourceLocation foreground = switch (this.bar) {
            default -> throw new IncompatibleClassChangeError();
            case DynamicStatusBar.VEHICLE_HEALTH -> AresHudTextures.VEHICLE_HEALTH_FG;
            case DynamicStatusBar.AIR -> AresHudTextures.AIR_BAR_FG;
            case DynamicStatusBar.JUMP -> AresHudTextures.JUMP_BAR_FG;
        };
        boolean rightToLeft = !this.bar.leftSide;
        RenderUtils.renderBar(guiGraphics, background, foreground, 0, 0, 100, 12, 0.7f, rightToLeft ? 18 : 9, rightToLeft ? 9 : 18, rightToLeft, 1.0f, 1.0f, 1.0f, 1.0f);
    }
}

